from typing import List
from collections import Counter

class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        if len(hand) % groupSize != 0:
            return False
        count = Counter(hand)
        for val in sorted(count):
            if count[val] > 0:
                needed = count[val]
                for k in range(val, val + groupSize):
                    if count[k] < needed:
                        return False
                    count[k] -= needed
        return True

class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        if (hand.size() % groupSize != 0) return false;
        map<int, int> count;
        for (int x : hand) count[x]++;
        for (auto const& [val, cnt] : count) {
            if (cnt > 0) {
                int needed = cnt;
                for (int i = 0; i < groupSize; i++) {
                    if (count[val + i] < needed) return false;
                    count[val + i] -= needed;
                }
            }
        }
        return true;
    }
};

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int x : hand) count.put(x, count.getOrDefault(x, 0) + 1);
        for (int val : count.keySet()) {
            int cnt = count.get(val);
            if (cnt > 0) {
                for (int i = 0; i < groupSize; i++) {
                    int nextVal = val + i;
                    if (count.getOrDefault(nextVal, 0) < cnt) return false;
                    count.put(nextVal, count.get(nextVal) - cnt);
                }
            }
        }
        return true;
    }
}

var isNStraightHand = function(hand, groupSize) {
    if (hand.length % groupSize !== 0) return false;
    const count = new Map();
    for (const x of hand) count.set(x, (count.get(x) || 0) + 1);
    const keys = Array.from(count.keys()).sort((a, b) => a - b);
    for (const val of keys) {
        const cnt = count.get(val);
        if (cnt > 0) {
            for (let i = 0; i < groupSize; i++) {
                const nextVal = val + i;
                if ((count.get(nextVal) || 0) < cnt) return false;
                count.set(nextVal, count.get(nextVal) - cnt);
            }
        }
    }
    return true;
};
